<script setup lang="ts">
import { computed, reactive } from 'vue'
import { useStudyStore } from '../stores/useStudyStore'
import { useGoogleServices } from '../composables/useGoogleServices'
import { useToast } from '../composables/useToast'
const store = useStudyStore(); store.hydrate(); const google = useGoogleServices(); const toast = useToast()
const form = reactive({ duracionSesionMinutos: store.settings.duracionSesionMinutos, tiempoInactividadSegundos: Math.round(store.settings.tiempoInactividadSegundos / 60), cantidadEjerciciosPorSesion: store.settings.cantidadEjerciciosPorSesion, horaEstudioPreferida: store.settings.horaEstudioPreferida })
const tokenMinutes = computed(() => store.googleAuth.expiresAt ? Math.max(0, Math.round((store.googleAuth.expiresAt - Date.now()) / 60000)) : 0)
function saveSettings() { if (form.duracionSesionMinutos < 10 || form.duracionSesionMinutos > 90 || form.tiempoInactividadSegundos < 1 || form.tiempoInactividadSegundos > 15 || form.cantidadEjerciciosPorSesion < 1) { toast.showWarning('Revisa los valores permitidos de tus preferencias.'); return } store.updateSettings({ duracionSesionMinutos: form.duracionSesionMinutos, tiempoInactividadSegundos: form.tiempoInactividadSegundos * 60, cantidadEjerciciosPorSesion: form.cantidadEjerciciosPorSesion, horaEstudioPreferida: form.horaEstudioPreferida }); toast.showSuccess('Preferencias guardadas.') }
async function verify() { try { await google.verifyConnection(); toast.showSuccess('La conexión con Google funciona correctamente.') } catch (reason) { toast.showError(reason instanceof Error ? reason.message : 'No se pudo verificar Google.') } }
async function backup() { try { await google.backupProgress(); toast.showSuccess('Respaldo sincronizado en Google Drive.') } catch (reason) { toast.showError(reason instanceof Error ? reason.message : 'No se pudo sincronizar el respaldo.') } }
function exportJson() { const blob = new Blob([JSON.stringify({ weeks: store.weeks, incidents: store.incidents, examResults: store.examResults }, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'discretaflow_progress.json'; anchor.click(); URL.revokeObjectURL(url); toast.showSuccess('Respaldo JSON descargado.') }
</script>
<template><main class="mx-auto max-w-5xl px-5 py-8"><div class="mb-8"><p class="text-sm font-bold uppercase tracking-widest text-indigo-400">Preferencias</p><h1 class="mt-2 text-3xl font-black text-white">Configuración & Integraciones</h1></div><div class="grid gap-5"><section class="panel"><h2 class="text-lg font-bold text-white">Google Drive y Google Calendar</h2><div v-if="store.isGoogleTokenValid" class="mt-4 flex flex-wrap items-center justify-between gap-4"><div><p class="font-semibold text-emerald-300">{{ store.googleAuth.userName || store.googleAuth.userEmail }}</p><p class="text-sm text-slate-400">{{ store.googleAuth.userEmail }} · {{ tokenMinutes }} min restantes</p></div><div class="flex gap-2"><button class="btn-secondary" @click="verify">Probar conexión</button><button class="btn-danger" @click="google.disconnect">Desconectar cuenta</button></div></div><button v-else class="btn-primary mt-4" @click="google.connect">Conectar cuenta de Google</button></section><section class="panel"><h2 class="text-lg font-bold text-white">Parámetros de Estudio y Enfoque</h2><form class="mt-4 grid gap-4 sm:grid-cols-2" @submit.prevent="saveSettings"><label>Duración de sesión (10–90 min)<input v-model.number="form.duracionSesionMinutos" type="number" min="10" max="90" /></label><label>Inactividad antes de pausar (1–15 min)<input v-model.number="form.tiempoInactividadSegundos" type="number" min="1" max="15" /></label><label>Ejercicios por sesión<input v-model.number="form.cantidadEjerciciosPorSesion" type="number" min="1" max="20" /></label><label>Hora preferida<input v-model="form.horaEstudioPreferida" type="time" /></label><button class="btn-primary sm:col-span-2">Guardar preferencias</button></form></section><section class="panel"><h2 class="text-lg font-bold text-white">Respaldo de Progreso</h2><div class="mt-4 flex flex-wrap gap-3"><button class="btn-primary" :disabled="!store.isGoogleTokenValid" @click="backup">Sincronizar respaldo con Google Drive</button><button class="btn-secondary" @click="exportJson">Exportar JSON local</button></div></section></div></main></template>
